<?php
require __DIR__.'/runtime_bootstrap.php';
use App\Models\User;use App\Models\DatingRound;use App\Models\DatingRoundChannel;use App\Services\MatchingRoundService;use App\Services\MatchingRunService;use App\Services\SlowDatingService;use App\Domain\Matching\RoundState;use App\Domain\Matching\OperationAction;
set_exception_handler(function(Throwable $e){fwrite(STDERR,get_class($e).':'.$e->getMessage());exit(1);});
$input=$argv[1];$label=$argv[2];if(!preg_match('/^[a-z0-9_-]+$/',$label)||file_exists(__DIR__.'/fixture-'.$label.'.private.json'))exit(32);
